import dev.ohs.fhir.engine.toTimeZoneString
import dev.ohs.fhir.model.r4.Bundle
import dev.ohs.fhir.model.r4.OperationOutcome
import dev.ohs.fhir.model.r4.Resource
import dev.ohs.fhir.model.r4.terminologies.ResourceType

typealias ResourceSearchParams = Map<ResourceType, ParamMap>

/**
 * [DownloadWorkManager] implementation based on the provided [ResourceSearchParams] to generate
 * [Resource] search queries and parse [Bundle.BundleType.Searchset] type [Bundle]. This
 * implementation takes a DFS approach and downloads all available resources for a particular
 * [ResourceType] before moving on to the next [ResourceType].
 */
class ResourceParamsBasedDownloadWorkManager(
  syncParams: ResourceSearchParams,
  val context: TimestampContext,
) : DownloadWorkManager {
  private val resourcesToDownloadWithSearchParams = ArrayDeque(syncParams.entries)
  private val urlOfTheNextPagesToDownloadForAResource = ArrayDeque<String>()

  override suspend fun getNextRequest(): DownloadRequest? {
    if (urlOfTheNextPagesToDownloadForAResource.isNotEmpty()) {
      return urlOfTheNextPagesToDownloadForAResource.removeFirstOrNull()?.let {
        DownloadRequest.of(it)
      }
    }

    return resourcesToDownloadWithSearchParams.removeFirstOrNull()?.let { (resourceType, params) ->
      val newParams =
        params.toMutableMap().apply { putAll(getLastUpdatedParam(resourceType, params, context)) }

      DownloadRequest.of("${resourceType.name}?${newParams.concatParams()}")
    }
  }

  /**
   * Returns the map of resourceType and URL for summary of total count for each download request
   */
  override suspend fun getSummaryRequestUrls(): Map<ResourceType, String> {
    return resourcesToDownloadWithSearchParams.associate { (resourceType, params) ->
      val newParams =
        params.toMutableMap().apply {
          putAll(getLastUpdatedParam(resourceType, params, context))
          putAll(getSummaryParam(params))
        }

      resourceType to "${resourceType.name}?${newParams.concatParams()}"
    }
  }

  private suspend fun getLastUpdatedParam(
    resourceType: ResourceType,
    params: ParamMap,
    context: TimestampContext,
  ): MutableMap<String, String> {
    val newParams = mutableMapOf<String, String>()
    if (!params.containsKey(SyncDataParams.SORT_KEY)) {
      newParams[SyncDataParams.SORT_KEY] = SyncDataParams.LAST_UPDATED_KEY
    }
    if (!params.containsKey(SyncDataParams.LAST_UPDATED_KEY)) {
      val lastUpdate = context.getLasUpdateTimestamp(resourceType)
      if (!lastUpdate.isNullOrEmpty()) {
        newParams[SyncDataParams.LAST_UPDATED_KEY] = "$GREATER_THAN_PREFIX$lastUpdate"
      }
    }
    return newParams
  }

  private fun getSummaryParam(params: ParamMap): MutableMap<String, String> {
    val newParams = mutableMapOf<String, String>()
    if (!params.containsKey(SyncDataParams.SUMMARY_KEY)) {
      newParams[SyncDataParams.SUMMARY_KEY] = SyncDataParams.SUMMARY_COUNT_VALUE
    }
    return newParams
  }

  override suspend fun processResponse(response: Resource): Collection<Resource> {
    if (response is OperationOutcome) {
      throw IllegalStateException(response.issue.firstOrNull()?.diagnostics?.value)
    }

    if ((response !is Bundle || response.type.value != Bundle.BundleType.Searchset)) {
      return emptyList()
    }

    response.link
      .firstOrNull { component -> component.relation.value == "next" }
      ?.url
      ?.let { next -> next.value?.let { urlOfTheNextPagesToDownloadForAResource.add(it) } }

    return response.entry
      .mapNotNull { it.resource }
      .also { resources ->
        resources
          .groupBy { ResourceType.valueOf(it.resourceType) }
          .entries
          .forEach { map ->
            map.value
              .mapNotNull { it.lastUpdated }
              .let { lastUpdatedList ->
                if (lastUpdatedList.isNotEmpty()) {
                  context.saveLastUpdatedTimestamp(
                    map.key,
                    lastUpdatedList.maxOrNull()?.toTimeZoneString(),
                  )
     * multiple changes to the same resource if applicable), and bundles them into a single HTTP
     * request for uploading to the server.
     *
     * Note: Currently, only the `squash = true` scenario is supported. When `squash = false`, the
     * bundle request would need to support chunking to accommodate multiple changes for the same
     * resource. This functionality is not yet implemented.
     *
     * @param methodForCreate The HTTP method to use for creating new resources (PUT or POST).
     * @param methodForUpdate The HTTP method to use for updating existing resources (PUT or PATCH).
     * @param squash Whether to combine multiple changes to the same resource into a single update.
     *   Only `true` is supported currently.
     * @param bundleSize The maximum number of resources to include in a single bundle.
     * @return An [UploadStrategy] configured for bundle requests.
     */
    fun forBundleRequest(
      methodForCreate: HttpCreateMethod,
      methodForUpdate: HttpUpdateMethod,
      squash: Boolean,
      bundleSize: Int,
    ): UploadStrategy {
      if (methodForUpdate == HttpUpdateMethod.PUT) {
        throw NotImplementedError("PUT for UPDATE not supported yet.")
      }
      if (!squash) {
        throw NotImplementedError("No squashing with bundle uploading not supported yet.")
      }
      return UploadStrategy(
        localChangesFetchMode = LocalChangesFetchMode.AllChanges,
        patchGeneratorMode = PatchGeneratorMode.PerResource,
        requestGeneratorMode =
          UploadRequestGeneratorMode.BundleRequest(
            methodForCreate.toBundleHttpVerb(),
            methodForUpdate.toBundleHttpVerb(),
            bundleSize,
          ),
      )
    }

    /**
     * Creates an [UploadStrategy] for sending individual requests for each change.
     *
     * This strategy can either fetch all changes or only the earliest change for each resource,
     * generate patches per resource or per change, and send individual HTTP requests for each
     * change.
     *
     * Note: PUT for update with squash set as false is not supported as that would require storing
     * full resource for each change.
     *
     * @param methodForCreate The HTTP method to use for creating new resources (PUT or POST).
     * @param methodForUpdate The HTTP method to use for updating existing resources (PUT or PATCH).
     * @param squash Whether to squash multiple changes to the same resource into a single update.
     *   If `true`, all changes for a resource are fetched and patches are generated per resource.
     *   If `false`, only the earliest change is fetched and patches are generated per change.
     * @return An [UploadStrategy] configured for individual requests.
     */
    fun forIndividualRequest(
      methodForCreate: HttpCreateMethod,
      methodForUpdate: HttpUpdateMethod,
      squash: Boolean,
    ): UploadStrategy {
      if (methodForUpdate == HttpUpdateMethod.PUT) {
        throw NotImplementedError("PUT for UPDATE not supported yet.")
      }
      require(methodForUpdate != HttpUpdateMethod.PUT || squash) {
        "Http method PUT not supported for UPDATE with squash set as false."
      }
      return UploadStrategy(
        localChangesFetchMode =
          if (squash) LocalChangesFetchMode.PerResource else LocalChangesFetchMode.EarliestChange,
        patchGeneratorMode =
          if (squash) PatchGeneratorMode.PerResource else PatchGeneratorMode.PerChange,
        requestGeneratorMode =
          UploadRequestGeneratorMode.UrlRequest(
            methodForCreate.toHttpVerb(),
            methodForUpdate.toHttpVerb(),
          ),
      )
    }
  }
}

